package com.example.fokusimport android.os.Bundleimport android.os.Handlerimport android.os.Looperimport android.view.LayoutInflaterimport android.view.MotionEventimport android.view.Viewimport android.view.ViewGroupimport android.widget.LinearLayoutimport android.widget.*import androidx.fragment.app.Fragmentimport androidx.lifecycle.Observerimport androidx.lifecycle.ViewModelProviderimport com.example.fokus.activities.MainActivityimport com.example.fokus.api.saveSettingsimport com.example.fokus.fragments.GuideFragmentimport com.example.fokus.fragments.SharedViewModelclass SettingsFragment : Fragment() {    private lateinit var tvSettings: TextView    private lateinit var tvAccountSettings: TextView    private lateinit var tvPomodoroSettings: TextView    private lateinit var tvSoundSettings: TextView    private lateinit var tvGuides: TextView    private lateinit var increase: ImageButton    private lateinit var decrease: ImageButton    private lateinit var volume: TextView    private val save = saveSettings()    override fun onCreateView(        inflater: LayoutInflater, container: ViewGroup?,        savedInstanceState: Bundle?    ): View? {        return inflater.inflate(R.layout.fragment_settings, container, false)    }    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {        super.onViewCreated(view, savedInstanceState)        val viewModel = ViewModelProvider(requireActivity())[SharedViewModel::class.java]        val changeUsernameLayout: LinearLayout = view.findViewById(R.id.changeuserBtn)        val changePasswordLayout: LinearLayout = view.findViewById(R.id.changepassBtn)        val changeEmailLayout: LinearLayout = view.findViewById(R.id.changeemailBtn)        val changePfpLayout: LinearLayout = view.findViewById(R.id.changepfpBtn)        val changePTimerFragment: LinearLayout = view.findViewById(R.id.changeptimerBtn)        val changeSBTimerFragment: LinearLayout = view.findViewById(R.id.changesbtimerBtn)        val changeLBTimerFragment: LinearLayout = view.findViewById(R.id.changelbtimerBtn)        val guideFragment: LinearLayout = view.findViewById(R.id.guideBtn)        val handler = Handler(Looper.getMainLooper())        var isIncreasing = false        var isDecreasing = false        tvSettings = view.findViewById(R.id.tvSettings)        tvAccountSettings = view.findViewById(R.id.tvAccountSettings)        tvPomodoroSettings = view.findViewById(R.id.tvPomodoroSettings)        tvSoundSettings = view.findViewById(R.id.tvSoundSettings)        tvGuides = view.findViewById(R.id.tvGuides)        increase = view.findViewById(R.id.increaseBtn)        decrease = view.findViewById(R.id.reduceBtn)        volume = view.findViewById(R.id.volumeTt)        volume.text = save.getVolume(requireContext().applicationContext).toString()        changeUsernameLayout.setOnClickListener {            (activity as MainActivity).switchedTabs += 1            requireActivity().supportFragmentManager.beginTransaction()                .replace(R.id.main, ChangeUsernameFragment())                .addToBackStack(null)                .commit()        }        changePasswordLayout.setOnClickListener {            (activity as MainActivity).switchedTabs += 1            requireActivity().supportFragmentManager.beginTransaction()                .replace(R.id.main, ChangePasswordFragment())                .addToBackStack(null)                .commit()        }        changeEmailLayout.setOnClickListener {            (activity as MainActivity).switchedTabs += 1            requireActivity().supportFragmentManager.beginTransaction()                .replace(R.id.main, ChangeEmailFragment())                .addToBackStack(null)                .commit()        }        changePfpLayout.setOnClickListener {            (activity as MainActivity).switchedTabs += 1            requireActivity().supportFragmentManager.beginTransaction()                .replace(R.id.main, ChangePfpFragment())                .addToBackStack(null)                .commit()        }        changePTimerFragment.setOnClickListener {            (activity as MainActivity).switchedTabs += 1            requireActivity().supportFragmentManager.beginTransaction()                .replace(R.id.main, ChangePTimerFragment())                .addToBackStack(null)                .commit()        }        changeSBTimerFragment.setOnClickListener {            (activity as MainActivity).switchedTabs += 1            requireActivity().supportFragmentManager.beginTransaction()                .replace(R.id.main, ChangeSBTimerFragment())                .addToBackStack(null)                .commit()        }        changeLBTimerFragment.setOnClickListener {            (activity as MainActivity).switchedTabs += 1            requireActivity().supportFragmentManager.beginTransaction()                .replace(R.id.main, ChangeLBTimerFragment())                .addToBackStack(null)                .commit()        }        guideFragment.setOnClickListener {            (activity as MainActivity).switchedTabs += 1            requireActivity().supportFragmentManager.beginTransaction()                .replace(R.id.main, GuideFragment())                .addToBackStack(null)                .commit()        }        viewModel.textColor.observe(viewLifecycleOwner, Observer { color ->            tvSettings.setTextColor(color)            tvAccountSettings.setTextColor(color)            tvPomodoroSettings.setTextColor(color)            tvSoundSettings.setTextColor(color)            tvGuides.setTextColor(color)        })        val increaseVolume = object : Runnable {            override fun run() {                val currentVolume = volume.text.toString().toInt()                if (currentVolume < 100 && isIncreasing) {                    val newVolume = currentVolume + 1                    volume.text = newVolume.toString()                    (requireActivity() as MainActivity).changeVolume(newVolume)                    save.saveSilent(requireContext().applicationContext, false)                    save.saveVolume(requireContext().applicationContext, newVolume)                    handler.postDelayed(this, 100)                }            }        }        val decreaseVolume = object : Runnable {            override fun run() {                val currentVolume = volume.text.toString().toInt()                if (currentVolume > 0 && isDecreasing) {                    val newVolume = currentVolume - 1                    volume.text = newVolume.toString()                    (requireActivity() as MainActivity).changeVolume(newVolume)                    save.saveVolume(requireContext().applicationContext, newVolume)                    handler.postDelayed(this, 100)                }            }        }        increase.setOnClickListener {            val currentVolume = volume.text.toString().toInt()            if (currentVolume < 100) {                val newVolume = currentVolume + 1                volume.text = newVolume.toString()                (requireActivity() as MainActivity).changeVolume(newVolume)                save.saveSilent(requireContext().applicationContext, false)                save.saveVolume(requireContext().applicationContext, newVolume)            }        }        increase.setOnLongClickListener {            isIncreasing = true            handler.post(increaseVolume)            true        }        increase.setOnTouchListener { _, event ->            if (event.action == MotionEvent.ACTION_UP || event.action == MotionEvent.ACTION_CANCEL) {                isIncreasing = false            }            false        }        decrease.setOnClickListener {            val currentVolume = volume.text.toString().toInt()            if (currentVolume > 0) {                val newVolume = currentVolume - 1                volume.text = newVolume.toString()                (requireActivity() as MainActivity).changeVolume(newVolume)                save.saveVolume(requireContext().applicationContext, newVolume)            }        }        decrease.setOnLongClickListener {            isDecreasing = true            handler.post(decreaseVolume)            true        }        decrease.setOnTouchListener { _, event ->            if (event.action == MotionEvent.ACTION_UP || event.action == MotionEvent.ACTION_CANCEL) {                isDecreasing = false            }            false        }    }}